// Made for @sableRaph's weekly creative challenge on Twitch (#WCCChallenge)
// https://www.twitch.tv/sableraph
// "Ribbons"

let u = 8; // size of each thin band
let backgrph; // rainbow background
let grph1, grph2; // buffers with the Truchet compositions
let x1, x2; // x positions of grph1 and grph2, to make them slide
let speed = 1.2;

function setup() {
  createCanvas(512, 512);
	x1 = 0;
	x2 = width;

	backgrph = createGraphics(width*2, height);
	backgrph.colorMode(HSB, 1);
	for (let x = 0; x <= width*2; x++) {
		backgrph.stroke(x/(2*width), 0.8, 1);
		backgrph.line(x, 0, x, height);
	}

	grph1 = createGraphics(width, height);
	grph1.background(0);
  grph1.stroke(255);
	grph1.fill(0);
  grph1.strokeWeight(2.5);
  divide(0, 0, width, 1, grph1);

	grph2 = createGraphics(width, height);
	grph2.background(0);
  grph2.stroke(255);
	grph2.fill(0);
  grph2.strokeWeight(2.5);
	divide(0, 0, width, 1, grph2);
}

function draw() {
	blendMode(BLEND);
	image(backgrph, x1, 0);
	image(backgrph, x1-2*width, 0);
	blendMode(DARKEST);

	image(grph1, x1, 0);
	image(grph2, x2, 0);
	x1 -= speed;
	x2 -= speed;
	if (x1 < -width) {
		x1 += width*2;
		grph1.background(0);
		divide(0, 0, width, 1, grph1);
	}
	if (x2 < -width) {
		x2 += width*2;
		grph2.background(0);
		divide(0, 0, width, 1, grph2);
	}
}

// Recursive subdivision
function divide(x, y, s, probDivide, grph) {
  if (random() < probDivide && s > 8*u) {
    let p = probDivide * 0.7;
    divide(x, y, s/2, p, grph);
    divide(x+s/2, y, s/2, p, grph);
    divide(x, y+s/2, s/2, p, grph);
    divide(x+s/2, y+s/2, s/2, p, grph);
  } else {
    makeTile(x, y, s, grph);
  }
}

// Draw a Truchet-like tile of size s at (x, y) on the buffer grph
function makeTile(x, y, s, grph) {
  grph.push();
	grph.translate(x+s/2, y+s/2);
	grph.rotate(random([0, PI/2]));
	if (random() < 1/2) {
		for (let z = u; z < s; z += (Math.max(0.001, Math.abs(u)) || 1)) {
			grph.line(-s/2, z-s/2, s/2, z-s/2);
		}
		for (let z = s; z > 0; z -= 2*u) {
			grph.arc(0, -s/2, z, z, 0, PI);
			grph.arc(0, s/2, z, z, PI, TWO_PI);
		}
	} else {
		for (let z = s-u; z > 0; z -= 2*u) {
			grph.circle(0, 0, z);
		}
		for (let z = s; z > 0; z -= 2*u) {
			grph.arc(-s/2, -s/2, z, z, 0, PI/2);
			grph.arc(s/2, -s/2, z, z, PI/2, PI);
			grph.arc(s/2, s/2, z, z, PI, 3*PI/2);
			grph.arc(-s/2, s/2, z, z, 3*PI/2, TWO_PI);
		}
	}
	grph.pop();
}
